--- compute_funnel.py ---
import sqlite3, json, datetime

STEPS = ['install', 'tutorial_complete', 'first_match', 'purchase']
c = sqlite3.connect('analytics.db')
users = {u: p for u, p in c.execute('select user_id, platform from users where is_test = 0')}
events = {}
for uid, name, ts in c.execute('select user_id, name, ts from events'):
    if uid not in users or name not in STEPS:
        continue
    events.setdefault(uid, {}).setdefault(name, []).append(ts)
for d in events.values():
    for v in d.values():
        v.sort()

funnel = {}
for platform in sorted(set(users.values())):
    counts = {s: 0 for s in STEPS}
    for uid, plat in users.items():
        if plat != platform:
            continue
        last = None
        for s in STEPS:
            cand = [t for t in events.get(uid, {}).get(s, []) if last is None or t >= last]
            if not cand:
                break
            last = cand[0]
            counts[s] += 1
    funnel[platform] = counts

out = {}
for plat, counts in funnel.items():
    rows = []
    biggest = None
    for i, s in enumerate(STEPS):
        n = counts[s]
        if i == 0:
            rows.append({'step': s, 'players': n, 'conversion_from_previous': None,
                         'dropped_from_previous': None})
            continue
        prev = counts[STEPS[i-1]]
        conv = n / prev if prev else None
        dropped = prev - n
        rows.append({'step': s, 'players': n,
                     'conversion_from_previous': round(conv, 4) if conv is not None else None,
                     'dropped_from_previous': dropped})
        if biggest is None or conv < biggest['conversion']:
            biggest = {'step': s, 'from_step': STEPS[i-1], 'conversion': round(conv, 4),
                       'players_lost': dropped, 'players_before': prev, 'players_after': n}
    out[plat] = {'funnel': rows, 'biggest_drop': biggest}

result = {
    'source': 'analytics.db; rules: METRICS.md',
    'assumptions': [
        'Steps are chained per player: each step uses the first event at or after that player\'s previous valid step; a player who fails a step cannot appear at later steps.',
        'Test accounts (users.is_test = 1) and events whose user_id is absent from users are excluded.',
        'install has no previous step, so its conversion and drop are null; biggest_drop considers tutorial_complete, first_match, purchase.',
        'Conversion is players at step / players at the immediately previous step, rounded to 4 decimals; biggest_drop is the step with the lowest conversion, ties would list the earliest.'
    ],
    'platforms': out
}
with open('result.json', 'w', encoding='utf-8') as f:
    json.dump(result, f, indent=2)
print(json.dumps(result, indent=2))


